query:
PREFIX energia: <https://w3id.org/rastro/energia#>

SELECT (SUM(?petroleo * ?porcentaje / 100) AS ?petroleo_m3)
WHERE {
  {
    SELECT DISTINCT ?empresa
    WHERE {
      { ?empresa energia:name ?nombre . }
      UNION
      { ?nombre_empresa energia:company ?empresa ; energia:nameInSource ?nombre . }
      FILTER(REGEX(UCASE(STR(?nombre)), "^TECPETROL(\\s+S\\.?A\\.?)?$"))
    }
  }
  ?participacion a energia:Stake ;
    energia:partner ?empresa ;
    energia:percent ?porcentaje ;
    energia:inConcession ?concesion .
  ?produccion a energia:WellProduction ;
    energia:inConcession ?concesion ;
    energia:oil ?petroleo .
}
LIMIT 50
